package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.Activity;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import java.text.SimpleDateFormat;import java.util.*;import org.json.*;
/** Window-only dimming. No system brightness, sleep setting or alarm mutations. */
public final class DeskClockActivity extends Activity {
 private Face face;private final Handler handler=new Handler();private boolean visible,keep;private int level=1,battery;private boolean plugged;private static final float[] LEVELS={.05f,.10f,.20f,.40f};
 private final Runnable tick=new Runnable(){public void run(){if(visible){face.invalidate();handler.postDelayed(this,60000-System.currentTimeMillis()%60000);}}};
 private final BroadcastReceiver changes=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(Intent.ACTION_BATTERY_CHANGED.equals(i.getAction())){battery=Math.max(0,Math.min(100,i.getIntExtra(BatteryManager.EXTRA_LEVEL,0)*100/Math.max(1,i.getIntExtra(BatteryManager.EXTRA_SCALE,100))));plugged=i.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)!=0;}face.invalidate();}};
 public void onCreate(Bundle b){super.onCreate(b);level=Math.max(0,Math.min(3,getSharedPreferences("desk-clock",0).getInt("brightness",1)));keep=getSharedPreferences("desk-clock",0).getBoolean("keep",false);getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);face=new Face();setContentView(face);window();}
 private void window(){WindowManager.LayoutParams a=getWindow().getAttributes();a.screenBrightness=LEVELS[level];getWindow().setAttributes(a);if(keep)getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);face.invalidate();}
 protected void onResume(){super.onResume();visible=true;IntentFilter f=new IntentFilter(Intent.ACTION_BATTERY_CHANGED);f.addAction(Intent.ACTION_TIME_CHANGED);f.addAction(Intent.ACTION_TIMEZONE_CHANGED);registerReceiver(changes,f);handler.post(tick);}
 protected void onPause(){visible=false;handler.removeCallbacks(tick);unregisterReceiver(changes);getSharedPreferences("desk-clock",0).edit().putInt("brightness",level).putBoolean("keep",keep).apply();super.onPause();}
 private String next(){long when=Long.MAX_VALUE;try{JSONArray all=AlarmScheduler.alarms(this);for(int i=0;i<all.length();i++){JSONObject a=all.optJSONObject(i);if(a!=null&&a.optBoolean("enabled"))when=Math.min(when,AlarmScheduler.next(System.currentTimeMillis(),a));}}catch(RuntimeException ignored){}return when==Long.MAX_VALUE?L.t("Nicio alarmă activă"):L.t("Alarmă · ")+new SimpleDateFormat("EEE HH:mm",L.locale()).format(new Date(when));}
 public boolean dispatchKeyEvent(KeyEvent e){if(LeoActivity.isJackNavigationNoise(e))return true;return super.dispatchKeyEvent(e);}
 public boolean onKeyDown(int key,KeyEvent e){if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){level=Math.max(0,Math.min(3,level+(key==KeyEvent.KEYCODE_DPAD_UP?1:-1)));window();return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0){keep=!keep;window();}return true;}if(key==KeyEvent.KEYCODE_MENU){if(e.getRepeatCount()==0)new KeypadDialog(this,L.t("Ceas de birou"),new String[]{L.t("Deschide alarmele"),keep?L.t("Permite stingerea ecranului"):L.t("Păstrează ecranul aprins"),L.t("Ajutor")},new KeypadDialog.Action(){public void select(int n){if(n==0)startActivity(new Intent(DeskClockActivity.this,ClockActivity.class).putExtra("tab",1));else if(n==1){keep=!keep;window();}else startActivity(new Intent(DeskClockActivity.this,HelpActivity.class).putExtra("topic",2));}}).show();return true;}return super.onKeyDown(key,e);}
 private final class Face extends View{final Paint p=new Paint(3);Face(){super(DeskClockActivity.this);setFocusable(true);requestFocus();}void text(Canvas c,String s,int y,int size,int color){p.setColor(color);p.setTextSize(size);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create("sans-serif-light",0));while(p.measureText(s)>220)p.setTextSize(p.getTextSize()-1);c.drawText(s,120,y,p);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/320f);Appearance.Palette a=Appearance.palette(DeskClockActivity.this);c.drawColor(a.background);Date now=new Date();int drift=(int)(System.currentTimeMillis()/60000%3)-1;c.save();c.translate(drift*2,drift);text(c,L.t("LEO · CEAS DE BIROU"),40,12,a.accent);text(c,new SimpleDateFormat("HH:mm",Locale.ROOT).format(now),142,68,Color.WHITE);text(c,new SimpleDateFormat("EEEE, d MMMM",L.locale()).format(now),179,18,a.accent);text(c,next(),218,14,Color.WHITE);text(c,(plugged?L.t("Încărcare · "):L.t("Baterie · "))+battery+"%",244,14,a.accent);text(c,L.t("Luminozitate ")+Math.round(LEVELS[level]*100)+"% · ↑ / ↓",274,11,0xffbac6cd);text(c,keep?L.t("OK: permite repausul"):L.t("OK: păstrează ecranul aprins"),293,11,0xffbac6cd);c.restore();text(c,L.t("Opțiuni                         Înapoi"),315,11,Color.WHITE);c.restore();}}
}
